import{_ as l,r as t,o as i,c as u,e,a as s,s as p,d as a}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"特征 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"属性操作","slug":"属性操作","link":"#属性操作","children":[{"level":3,"title":"Nullable","slug":"nullable","link":"#nullable","children":[]},{"level":3,"title":"Hashable","slug":"hashable","link":"#hashable","children":[]},{"level":3,"title":"Purgeable","slug":"purgeable","link":"#purgeable","children":[]},{"level":3,"title":"Encryptable","slug":"encryptable","link":"#encryptable","children":[]},{"level":3,"title":"Sluggable","slug":"sluggable","link":"#sluggable","children":[]}]},{"level":2,"title":"排序和重排序","slug":"排序和重排序","link":"#排序和重排序","children":[{"level":3,"title":"Sortable","slug":"sortable","link":"#sortable","children":[]},{"level":3,"title":"Simple Tree","slug":"simple-tree","link":"#simple-tree","children":[{"level":4,"title":"渲染","slug":"渲染","link":"#渲染","children":[]}]},{"level":3,"title":"Nested Tree","slug":"nested-tree","link":"#nested-tree","children":[{"level":4,"title":"创建根节点","slug":"创建根节点","link":"#创建根节点","children":[]},{"level":4,"title":"插入节点","slug":"插入节点","link":"#插入节点","children":[]},{"level":4,"title":"删除节点","slug":"删除节点","link":"#删除节点","children":[]},{"level":4,"title":"获取节点的嵌套级别","slug":"获取节点的嵌套级别","link":"#获取节点的嵌套级别","children":[]},{"level":4,"title":"移动节点","slug":"移动节点","link":"#移动节点","children":[]}]}]},{"level":2,"title":"实用功能","slug":"实用功能","link":"#实用功能","children":[{"level":3,"title":"Validation","slug":"validation","link":"#validation","children":[{"level":4,"title":"增强的验证规则","slug":"增强的验证规则","link":"#增强的验证规则","children":[]},{"level":4,"title":"获取验证错误","slug":"获取验证错误","link":"#获取验证错误","children":[]},{"level":4,"title":"覆盖验证","slug":"覆盖验证","link":"#覆盖验证","children":[]},{"level":4,"title":"自定义错误消息","slug":"自定义错误消息","link":"#自定义错误消息","children":[]},{"level":4,"title":"自定义属性名称","slug":"自定义属性名称","link":"#自定义属性名称","children":[]},{"level":4,"title":"动态验证规则","slug":"动态验证规则","link":"#动态验证规则","children":[]},{"level":4,"title":"自定义验证规则","slug":"自定义验证规则","link":"#自定义验证规则","children":[]}]},{"level":3,"title":"Soft Deleting","slug":"soft-deleting","link":"#soft-deleting","children":[{"level":4,"title":"查询软删除的模型","slug":"查询软删除的模型","link":"#查询软删除的模型","children":[]},{"level":4,"title":"永久删除模型","slug":"永久删除模型","link":"#永久删除模型","children":[]},{"level":4,"title":"软删除关联","slug":"软删除关联","link":"#软删除关联","children":[]},{"level":4,"title":"包含软删除的关联","slug":"包含软删除的关联","link":"#包含软删除的关联","children":[]}]},{"level":3,"title":"Multisite","slug":"multisite","link":"#multisite","children":[{"level":4,"title":"强制同步","slug":"强制同步","link":"#强制同步","children":[]},{"level":4,"title":"保存模型","slug":"保存模型","link":"#保存模型","children":[]}]},{"level":3,"title":"Revisionable","slug":"revisionable","link":"#revisionable","children":[]}]}],"relativePath":"3.x/zh-cn/extend/database/traits.md","filePath":"3.x/zh-cn/extend/database/traits.md"}'),r={name:"3.x/zh-cn/extend/database/traits.md"};function k(d,n,g,h,v,b){const o=t("pre-heading"),c=t("post-heading");return i(),u("div",null,[e(o),n[0]||(n[0]=s("h1",null,"特征",-1)),e(c),n[1]||(n[1]=p(`<p>模型特征用于实现通用功能。</p><h2 id="属性操作"><a href="#属性操作" class="header-anchor">#</a> 属性操作</h2><h3 id="nullable"><a href="#nullable" class="header-anchor">#</a> Nullable</h3><p>可空属性在留空时会被设置为 <code>NULL</code>。要在模型中使属性可空，请应用 <code>October\\Rain\\Database\\Traits\\Nullable</code> 特征并声明一个 <code>$nullable</code> 属性，其中包含要设为空的属性数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Nullable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$nullable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sku&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="hashable"><a href="#hashable" class="header-anchor">#</a> Hashable</h3><p>散列属性在首次设置到模型上时会立即被散列。要在模型中散列属性，请应用 <code>October\\Rain\\Database\\Traits\\Hashable</code> 特征并声明一个 <code>$hashable</code> 属性，其中包含要散列的属性数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Hashable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$hashable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="purgeable"><a href="#purgeable" class="header-anchor">#</a> Purgeable</h3><p>清除的属性在创建或更新模型时不会保存到数据库。要在模型中清除属性，请应用 <code>October\\Rain\\Database\\Traits\\Purgeable</code> 特征并声明一个 <code>$purgeable</code> 属性，其中包含要清除的属性数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Purgeable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$purgeable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>使用 <code>getOriginalPurgeValue</code> 方法查找模型保存后被清除的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">getOriginalPurgeValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，使用 <code>restorePurgedValues</code> 方法恢复所有被清除的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restorePurgedValues</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="encryptable"><a href="#encryptable" class="header-anchor">#</a> Encryptable</h3><p>与 <code>Hashable</code> 特征类似，加密属性在设置时会被加密，但在获取属性时也会被解密。要在模型中加密属性，请应用 <code>October\\Rain\\Database\\Traits\\Encryptable</code> 特征并声明一个 <code>$encryptable</code> 属性，其中包含要加密的属性数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Encryptable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$encryptable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;api_secret&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block warning"><p>加密属性与 <a href="./../system/models.html">jsonable 属性</a>不兼容。</p></div><h3 id="sluggable"><a href="#sluggable" class="header-anchor">#</a> Sluggable</h3><p>Slug 是在页面 URL 中常用的有意义的代码。要为模型自动生成唯一的 slug，请应用 <code>October\\Rain\\Database\\Traits\\Sluggable</code> 特征并声明一个 <code>$slugs</code> 属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sluggable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>$slugs</code> 属性应该是一个数组，其中键是 slug 的目标列，值是用于生成 slug 的源字符串。在上面的示例中，如果 <code>name</code> 列设置为 <strong>Cheyenne</strong>，则在模型创建之前 <code>slug</code> 列将被设置为 <strong>cheyenne</strong>、<strong>cheyenne-2</strong> 或 <strong>cheyenne-3</strong> 等。</p><p>要从多个源生成 slug，请将另一个数组作为源值传递：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;last_name&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Slug 仅在模型首次创建时生成。要覆盖或禁用此功能，只需手动设置 slug 属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Remy&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;custom-slug&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Slug will not be generated</span>
</code></pre></div><p>使用 <code>slugAttributes</code> 方法在更新模型时重新生成 slug：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">slugAttributes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="排序和重排序"><a href="#排序和重排序" class="header-anchor">#</a> 排序和重排序</h2><h3 id="sortable"><a href="#sortable" class="header-anchor">#</a> Sortable</h3><p>排序模型将在 <code>sort_order</code> 中存储一个数值，用于维护集合中每个模型的排序顺序。要将 <code>sort_order</code> 列添加到表中，您可以在迁移中使用 <code>integer</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要为模型存储排序顺序，请应用 <code>October\\Rain\\Database\\Traits\\Sortable</code> 特征并确保您的架构定义了供其使用的列。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您可以通过定义 <code>SORT_ORDER</code> 常量来修改用于标识排序顺序的键名。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">SORT_ORDER</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_sort_order_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>使用 <code>setSortableOrder</code> 方法设置多个记录的排序。数组包含按应出现的排序顺序排列的模型标识符。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果排序记录的子集，第二个数组用于提供排序顺序值的参考池。例如，以下将排序顺序列分别设置为 100、200 或 300。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="simple-tree"><a href="#simple-tree" class="header-anchor">#</a> Simple Tree</h3><p>简单树模型将使用 <code>parent_id</code> 列维护模型之间的父子关系。要将 <code>parent_id</code> 列添加到表中，您可以在迁移中使用 <code>integer</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要使用简单树，请应用 <code>October\\Rain\\Database\\Traits\\SimpleTree</code> 特征。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>此特征将自动注入两个名为 <code>parent</code> 和 <code>children</code> 的<a href="./relations.html">模型关联</a>，相当于以下定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;parent&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;children&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>您不需要自己定义这些关联，但是，您可以通过定义 <code>PARENT_ID</code> 常量来修改用于标识父级的键名：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">PARENT_ID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_parent_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>使用此特征的模型集合将返回 <code>October\\Rain\\Database\\TreeCollection</code> 类型，该类型添加了 <code>toNested</code> 方法。要构建预加载的树结构，请返回带有预加载关联的记录。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">toNested</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="渲染"><a href="#渲染" class="header-anchor">#</a> 渲染</h4><p>为了渲染所有级别的项目及其子项，您可以使用递归处理</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> renderChildren<span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> item<span class="token punctuation">.</span>children <span class="token operator">is</span> <span class="token operator">not</span> empty <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> child <span class="token operator">in</span> item<span class="token punctuation">.</span>children <span class="token delimiter punctuation">%}</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>name <span class="token delimiter punctuation">}}</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> _self_<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>child<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as nav <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> nav<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>category<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h3 id="nested-tree"><a href="#nested-tree" class="header-anchor">#</a> Nested Tree</h3>`,56)),n[2]||(n[2]=s("p",null,[s("a",{href:"https://en.wikipedia.org/wiki/Nested_set_model",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("嵌套集模型"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a("是一种使用 "),s("code",null,"parent_id"),a("、"),s("code",null,"nest_left"),a("、"),s("code",null,"nest_right"),a(" 和 "),s("code",null,"nest_depth"),a(" 列维护模型层次结构的高级技术。要将这些列添加到表中，您可以在迁移中使用这些方法。")],-1)),n[3]||(n[3]=p(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_left&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_right&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_depth&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要使用嵌套集模型，请应用 <code>October\\Rain\\Database\\Traits\\NestedTree</code> 特征。<code>SimpleTree</code> 特征的所有功能在此模型中都固有可用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="创建根节点"><a href="#创建根节点" class="header-anchor">#</a> 创建根节点</h4><p>默认情况下，所有节点都创建为根节点：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$root</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Root category&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，您可能需要将现有节点转换为根节点：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">makeRoot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您也可以将其 <code>parent_id</code> 列设为 null，效果与 <code>makeRoot</code> 相同。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token property">parent_id</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="插入节点"><a href="#插入节点" class="header-anchor">#</a> 插入节点</h4><p>您可以直接通过关联插入新节点：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span> <span class="token operator">=</span> <span class="token variable">$root</span><span class="token operator">-&gt;</span><span class="token function">children</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 1&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者对现有节点使用 <code>makeChildOf</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child2</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 2&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$child2</span><span class="token operator">-&gt;</span><span class="token function">makeChildOf</span><span class="token punctuation">(</span><span class="token variable">$root</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="删除节点"><a href="#删除节点" class="header-anchor">#</a> 删除节点</h4><p>当使用 <code>delete</code> 方法删除节点时，该节点的所有后代也将被删除。请注意，子模型的删除<a href="./../system/models.html">模型事件</a>不会被触发。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="获取节点的嵌套级别"><a href="#获取节点的嵌套级别" class="header-anchor">#</a> 获取节点的嵌套级别</h4><p><code>getLevel</code> 方法将返回节点的当前嵌套级别或深度。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 根节点时为 0</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">getLevel</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre></div><h4 id="移动节点"><a href="#移动节点" class="header-anchor">#</a> 移动节点</h4><p>有几种移动节点的方法：</p><ul><li><code>moveLeft()</code>：找到左兄弟并移动到其左侧。</li><li><code>moveRight()</code>：找到右兄弟并移动到其右侧。</li><li><code>moveBefore($otherNode)</code>：将节点移动到...的左侧。</li><li><code>moveAfter($otherNode)</code>：将节点移动到...的右侧。</li><li><code>makeChildOf($otherNode)</code>：使节点成为...的子节点。</li><li><code>makeRoot()</code>：使当前节点成为根节点。</li></ul><h2 id="实用功能"><a href="#实用功能" class="header-anchor">#</a> 实用功能</h2><h3 id="validation"><a href="#validation" class="header-anchor">#</a> Validation</h3><p>October CMS 模型使用内置的 <a href="./../services/validation.html">Validator 类</a>。验证规则在模型类中定义为名为 <code>$rules</code> 的属性，且该类必须使用 <code>October\\Rain\\Database\\Traits\\Validation</code> 特征。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,16&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;alpha_num&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,8&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;confirmed&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;alpha_num&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,8&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您也可以使用<a href="./../services/validation.html">数组语法</a>的验证规则。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>模型在调用 <code>save</code> 方法时会自动验证自身。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Actual Person&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">email</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;a.person@example.tld&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;passw0rd&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// 如果模型无效则返回 false</span>
<span class="token variable">$success</span> <span class="token operator">=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>您也可以随时使用 <code>validate</code> 方法验证模型。</p></div><h4 id="增强的验证规则"><a href="#增强的验证规则" class="header-anchor">#</a> 增强的验证规则</h4><p><code>unique</code> 验证规则自动配置，不需要指定表名。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;unique&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p><code>required</code> 验证规则支持 <strong>create</strong> 和 <strong>update</strong> 修饰符，以仅在模型创建或更新时应用。以下仅在模型尚不存在时才是必需的。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required:create&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="获取验证错误"><a href="#获取验证错误" class="header-anchor">#</a> 获取验证错误</h4><p>当模型验证失败时，一个 <code>Illuminate\\Support\\MessageBag</code> 对象将附加到模型上。该对象包含验证失败消息。使用 <code>errors</code> 方法或 <code>$validationErrors</code> 属性获取验证错误消息集合实例。使用 <code>errors()-&gt;all()</code> 获取所有验证错误。使用 <code>validationErrors-&gt;get(&#39;attribute&#39;)</code> 获取<em>特定</em>属性的错误。</p><div class="custom-block tip"><p>Model 利用了 <code>MessagesBag</code> 对象，它有一种<a href="./../services/validation.html">简单而优雅的方法</a>来格式化错误。</p></div><h4 id="覆盖验证"><a href="#覆盖验证" class="header-anchor">#</a> 覆盖验证</h4><p><code>forceSave</code> 方法验证模型并保存，无论是否存在验证错误。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>

<span class="token comment">// 创建一个不经验证的用户</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="自定义错误消息"><a href="#自定义错误消息" class="header-anchor">#</a> 自定义错误消息</h4><p>就像 Validator 类一样，您可以使用<a href="./../services/validation.html">相同的语法</a>设置自定义错误消息。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The :attribute field is required.&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您也可以为验证规则的数组语法添加自定义错误消息。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The url is required&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.url.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The url needs to be a valid url&#39;</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The anchor text is required&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在上面的示例中，您可以为特定的验证规则编写自定义错误消息（这里我们使用了：<code>required</code>）。或者您可以使用 <code>*</code> 来选择其他所有内容（这里我们使用 <code>*</code> 为 <code>url</code> 验证规则添加了自定义消息）。</p><h4 id="自定义属性名称"><a href="#自定义属性名称" class="header-anchor">#</a> 自定义属性名称</h4><p>您也可以使用 <code>$attributeNames</code> 数组设置自定义属性名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attributeNames</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Email Address&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="动态验证规则"><a href="#动态验证规则" class="header-anchor">#</a> 动态验证规则</h4><p>您可以通过覆盖 <code>beforeValidate</code> <a href="./../system/models.html">模型事件</a>方法来动态应用规则。这里我们检查 <code>is_remote</code> 属性是否为 <code>false</code>，然后动态设置 <code>latitude</code> 和 <code>longitude</code> 属性为必填字段。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeValidate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">is_remote</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;latitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;longitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="自定义验证规则"><a href="#自定义验证规则" class="header-anchor">#</a> 自定义验证规则</h4><p>您也可以使用与 <code>Validator</code> 服务<a href="./../services/validation.html">相同的方式</a>创建自定义验证规则。</p><h3 id="soft-deleting"><a href="#soft-deleting" class="header-anchor">#</a> Soft Deleting</h3><p>当软删除模型时，它实际上并没有从数据库中删除。而是在记录上设置了一个 <code>deleted_at</code> 时间戳。要为模型启用软删除，请将 <code>October\\Rain\\Database\\Traits\\SoftDelete</code> 特征应用到模型并将 deleted_at 列添加到您的 <code>$dates</code> 属性中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;deleted_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>要将 <code>deleted_at</code> 列添加到表中，您可以在迁移中使用 <code>softDeletes</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">softDeletes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>现在，当您在模型上调用 <code>delete</code> 方法时，<code>deleted_at</code> 列将被设置为当前时间戳。当查询使用软删除的模型时，&quot;已删除&quot;的模型将不会包含在查询结果中。</p><p>要确定给定的模型实例是否已被软删除，请使用 <code>trashed</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">trashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="查询软删除的模型"><a href="#查询软删除的模型" class="header-anchor">#</a> 查询软删除的模型</h4><h5>包含软删除的模型</h5><p>如上所述，软删除的模型将自动从查询结果中排除。但是，您可以使用查询上的 <code>withTrashed</code> 方法强制软删除的模型出现在结果集中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>withTrashed</code> 方法也可以用于<a href="./relations.html">关联</a>查询：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">history</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>仅检索软删除的模型</h5><p><code>onlyTrashed</code> 方法将<strong>仅</strong>检索软删除的模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">onlyTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>恢复软删除的模型</h5><p>有时您可能希望&quot;取消删除&quot;一个软删除的模型。要将软删除的模型恢复为活跃状态，请在模型实例上使用 <code>restore</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您也可以在查询中使用 <code>restore</code> 方法来快速恢复多个模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 恢复单个模型实例...</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 恢复所有相关模型...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="永久删除模型"><a href="#永久删除模型" class="header-anchor">#</a> 永久删除模型</h4><p>有时您可能需要真正从数据库中删除模型。要从数据库中永久删除软删除的模型，请使用 <code>forceDelete</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 强制删除单个模型实例...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 强制删除所有相关模型...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="软删除关联"><a href="#软删除关联" class="header-anchor">#</a> 软删除关联</h4><p>当两个相关模型都启用了软删除时，您可以通过在<a href="./relations.html">关联定义</a>中定义 <code>softDelete</code> 选项来级联删除事件。在此示例中，如果用户模型被软删除，属于该用户的评论也将被软删除。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;softDelete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>如果相关模型不使用软删除特征，它将被视为与 <code>delete</code> 选项相同并被永久删除。</p></div><p>在相同条件下，当主模型被恢复时，所有使用 <code>softDelete</code> 选项的相关模型也将被恢复。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 恢复用户和评论</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="包含软删除的关联"><a href="#包含软删除的关联" class="header-anchor">#</a> 包含软删除的关联</h4><p>软删除的记录不包含在关联查找中，但是，您可以通过向查询添加 <code>withTrashed</code> 作用域来包含它们。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;scope&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;withTrashed&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="multisite"><a href="#multisite" class="header-anchor">#</a> Multisite</h3><p>将多站点应用于模型时，只有属于活跃站点的记录可供管理。活跃站点附加到记录上设置的 <code>site_id</code> 列。要为模型启用多站点，请应用 <code>October\\Rain\\Database\\Traits\\Multisite</code> 特征并使用 <code>$propagatable</code> 属性定义要在所有记录之间传播的属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Multisite</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$propagatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_code&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p><code>$propagatable</code> 是多站点特征所必需的，但可以留空数组以禁用任何属性的传播。</p></div><p>要将 <code>site_id</code> 列添加到表中，您可以在迁移中使用 <code>integer</code> 方法。也可以使用 <code>site_root_id</code> 通过根记录将记录链接在一起。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_root_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>现在，创建记录时它将被分配到活跃站点，切换到不同站点将自动传播新记录。更新记录时，传播的字段将复制到属于根记录的每条记录。</p><h4 id="强制同步"><a href="#强制同步" class="header-anchor">#</a> 强制同步</h4><p>在某些情况下，所有记录必须存在于每个站点中，例如分类和标签。您可以通过将 <code>$propagatableSync</code> 属性设置为 true 来强制每条记录在所有站点中都存在，默认值为 false。启用后，保存模型后，如果其他站点还没有相同的模型，它将为其他站点创建相同的模型。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$propagatableSync</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
</code></pre></div><p>使用<a href="./../../cms/resources/multisite.html">站点组</a>时，记录将传播到该组内的所有站点。这可以通过将 <code>$propagatableSync</code> 属性设置为包含配置选项的数组来控制。</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead></table></div><ul><li><strong>sync</strong> - 同步特定站点的逻辑，可用选项：<code>all</code>、<code>group</code>、<code>locale</code>。默认值：<code>group</code></li><li><strong>delete</strong> - 当任何记录被删除时删除所有链接的记录，默认值：<code>true</code></li><li><strong>except</strong> - 提供不应为新同步记录复制的属性名称</li></ul><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$propagatableSync</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;sync&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;all&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;delete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;except&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;description&#39;</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="保存模型"><a href="#保存模型" class="header-anchor">#</a> 保存模型</h4><p>使用多站点特征保存的模型默认不传播。使用 <code>savePropagate</code> 方法确保传播规则生效。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">savePropagate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="revisionable"><a href="#revisionable" class="header-anchor">#</a> Revisionable</h3><p>October CMS 模型可以通过存储修订来记录值变化的历史。要为模型存储修订，请应用 <code>October\\Rain\\Database\\Traits\\Revisionable</code> 特征并声明一个 <code>$revisionable</code> 属性，其中包含要监控变化的属性数组。您还需要定义一个名为 <code>revision_history</code> 的 <code>$morphMany</code> <a href="./relations.html">模型关联</a>，引用名为 <code>revisionable</code> 的 <code>System\\Models\\Revision</code> 类，这是修订历史数据存储的位置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Revisionable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$revisionable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$morphMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;revision_history&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Revision</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;revisionable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>默认情况下，最多保留 500 条记录，但是，您可以通过在模型上声明 <code>$revisionableLimit</code> 属性并设置新的限制值来修改此值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var int revisionableLimit as the maximum number records to keep.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$revisionableLimit</span> <span class="token operator">=</span> <span class="token number">8</span><span class="token punctuation">;</span>
</code></pre></div><p>修订历史可以像任何其他关联一样访问：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$history</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">revision_history</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$history</span> <span class="token keyword">as</span> <span class="token variable">$record</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">field</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; updated &#39;</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;from &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">old_value</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;to &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">new_value</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>修订记录可选地通过 <code>user_id</code> 属性支持用户关联。您可以在模型中包含 <code>getRevisionableUser</code> 方法来跟踪进行修改的用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getRevisionableUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,118))])}const y=l(r,[["render",k]]);export{f as __pageData,y as default};
